style.css:
@-moz-document domain("chat.openai.com") {
body {
    background-color: #ffd6e9 !important; /* Soft pink background */
    color: #ff69b4 !important; /* Hot pink text */
  }

  .text-gray-900, .text-black {
    color: #ff1493 !important; /* Deep pink for text */
  }

  .dark\:bg-gray-900 {
    background-color: #ffdde1 !important; /* Lighter pink chat background */
  }

  .bg-white {
    background-color: #ffe4ec !important; /* Soft pink panels */
  }

  button {
    background-color: #ffb6c1 !important; /* Cute pink buttons */
    border-radius: 10px !important; /* Rounded buttons */
    font-weight: bold !important;
    color: white !important;
  }

  input, textarea {
    background-color: #ffe4ec !important; /* Pink input fields */
    color: #ff1493 !important; /* Deep pink text */
    border-radius: 8px !important;
  }

  .hover\:bg-gray-700:hover {
    background-color: #ff85a2 !important; /* Soft pink hover effect */
  }
}
